// Single source of truth for API_REFERENCE.md and the Postman collection (generated by build-docs.js).
const J = 'JWT (Bearer access token)', I = 'API key (x-api-key)';
const common = { 401: 'Missing/invalid/expired token', 403: 'Role is not instructor', 404: 'Resource not found OR not assigned to the authenticated instructor (deliberately indistinguishable)' };
const set = (v, expr) => `pm.collectionVariables.set('${v}', ${expr});`;
const E = (group, name, method, path, o = {}) => ({ group, name, method, path, auth: o.auth || J, role: o.role || 'instructor', body: o.body, query: o.query, response: o.response || 'See envelope: { success: true, data }', errors: o.errors || common, test: o.test, expect: o.expect || 200, example: o.example });

module.exports = [
  // ---------- Auth
  E('Auth', 'Login', 'POST', '/auth/login', { auth: 'none', role: 'any active user', body: { email: '{{instructorEmail}}', password: '{{instructorPassword}}' },
    response: '{ accessToken, refreshToken, user }  (user never includes password/refresh hashes)', errors: { 400: 'Validation failed', 401: 'Invalid email or password (same message for unknown email)', 403: 'Account not active', 429: 'Rate limited (30 / 15 min per IP)' },
    test: `const d = pm.response.json().data; ${set('accessToken', 'd.accessToken')} ${set('refreshToken', 'd.refreshToken')} ${set('instructorId', 'd.user._id')}` }),
  E('Auth', 'Get current user', 'GET', '/auth/me', { role: 'any authenticated', response: 'User (safe fields)' }),
  E('Auth', 'Forgot password', 'POST', '/auth/forgot-password', { auth: 'none', role: '-', body: { email: '{{instructorEmail}}' }, response: '{ message } — identical whether or not the account exists', errors: { 400: 'Validation failed' } }),
  E('Auth', 'Reset password', 'POST', '/auth/reset-password', { auth: 'none', role: '-', body: { token: '<token from email>', password: 'NewPassw0rd' }, expect: 400, response: '{ message }', errors: { 400: 'Invalid/expired/used token or weak password' } }),
  E('Auth', 'Refresh tokens', 'POST', '/auth/refresh', { auth: 'none', role: '-', body: { refreshToken: '{{refreshToken}}' }, response: '{ accessToken, refreshToken, user } — the presented refresh token is rotated (single use); other devices stay signed in', errors: { 401: 'Invalid/used refresh token' },
    test: `const d = pm.response.json().data; ${set('accessToken', 'd.accessToken')} ${set('refreshToken', 'd.refreshToken')}` }),
  // ---------- Dashboard
  E('Dashboard', 'Dashboard', 'GET', '/instructor/dashboard', { response: '{ stats{assignedCourses,activeCohorts,totalCohorts,students,upcomingSessions,pendingGrading,unreadNotifications}, upcomingSessions[], pendingSubmissions[], recentAttendance[], recentActivity[] } — every value computed from the DB' }),
  // ---------- Courses
  E('Courses', 'List my courses', 'GET', '/instructor/courses', { response: 'Course[] each with assignedCohorts[]; only courses of cohorts assigned to me', test: set('courseId', 'pm.response.json().data[0]._id') }),
  E('Courses', 'Get course', 'GET', '/instructor/courses/{{courseId}}', { response: 'Course + assignedCohorts[] (with enrolledCount, sessionsCount)' }),
  // ---------- Cohorts
  E('Cohorts', 'List my cohorts', 'GET', '/instructor/cohorts', { query: { status: '', courseId: '' }, response: 'Cohort[] with course, enrolledCount, sessionsCount, nextSession', test: `const c = pm.response.json().data; ${set('cohortId', "(c.find(x => x.name === 'SSF-01') || c[0])._id")}` }),
  E('Cohorts', 'Get cohort (overview)', 'GET', '/instructor/cohorts/{{cohortId}}', { response: 'Cohort + course, instructor, enrolledCount, sessionsCount, assessmentsCount' }),
  E('Cohorts', 'Cohort students', 'GET', '/instructor/cohorts/{{cohortId}}/students', { response: 'Student progress rows' }),
  E('Cohorts', 'Cohort sessions', 'GET', '/instructor/cohorts/{{cohortId}}/sessions', { response: 'Session[] (+meta)' }),
  E('Cohorts', 'Cohort attendance summary', 'GET', '/instructor/cohorts/{{cohortId}}/attendance', { response: 'Per student { totalSessions, present, absent, pending, attendancePercentage|null }' }),
  E('Cohorts', 'Cohort assessments', 'GET', '/instructor/cohorts/{{cohortId}}/assessments', { response: 'Assessment[] with submission counts' }),
  E('Cohorts', 'Cohort progress', 'GET', '/instructor/cohorts/{{cohortId}}/progress', { response: 'Per student metrics (attendance + assessments); no invented overall %' }),
  // ---------- Sessions
  E('Sessions', 'List sessions', 'GET', '/instructor/sessions', { query: { cohortId: '', status: '', upcoming: '', page: '1', limit: '50' }, response: 'Session[] + meta{page,limit,total}', test: `const s = pm.response.json().data.filter(x => x.status !== 'cancelled'); ${set('sessionId', "(s.find(x => x.status === 'completed') || s[0])._id")}` }),
  E('Sessions', 'Create session', 'POST', '/instructor/sessions', { body: { cohortId: '{{cohortId}}', title: 'Postman Lab Session', description: 'Created from Postman', date: '2026-12-15', startTime: '09:00', endTime: '11:00', location: 'Lab 2' }, expect: 201, response: 'Session', errors: { ...common, 400: 'Validation (e.g. endTime <= startTime)' }, test: set('newSessionId', 'pm.response.json().data._id') }),
  E('Sessions', 'Get session', 'GET', '/instructor/sessions/{{sessionId}}', { response: 'Session + attendanceSummary{present,absent,pending}' }),
  E('Sessions', 'Update / cancel session', 'PATCH', '/instructor/sessions/{{newSessionId}}', { body: { title: 'Postman Lab Session (updated)' }, response: 'Session', errors: { ...common, 409: 'Session is cancelled' } }),
  // ---------- Students
  E('Students', 'List my students', 'GET', '/instructor/students', { query: { cohortId: '', search: '' }, response: 'One row per enrollment: { student, cohort, course, attendance{}, assessments{}, trainingStatus }', test: set('studentId', 'pm.response.json().data[0].student._id') }),
  E('Students', 'Student training profile', 'GET', '/instructor/students/{{studentId}}', { response: '{ student{name,email,externalStudentId}, progress[], attendanceRecords[], submissions[] } — academic data only' }),
  // ---------- Attendance
  E('Attendance', 'Session roster', 'GET', '/instructor/attendance/sessions/{{sessionId}}', { response: '{ session, roster:[{ student, status: present|absent|pending, markedAt }] }' }),
  E('Attendance', 'Save attendance', 'PUT', '/instructor/attendance/sessions/{{sessionId}}', { body: { records: [{ studentId: '{{studentId}}', status: 'present' }] }, response: 'Updated roster', errors: { ...common, 400: 'Invalid status', 409: 'Session cancelled', 422: 'A student is not actively enrolled in the cohort' } }),
  E('Attendance', 'Cohort attendance records', 'GET', '/instructor/attendance/cohorts/{{cohortId}}', { response: 'Per student totals + attendancePercentage (present ÷ recorded; null when nothing recorded). No threshold applied.' }),
  // ---------- Assessments
  E('Assessments', 'Create assessment (draft)', 'POST', '/instructor/assessments', { body: { cohortId: '{{cohortId}}', title: 'Postman Assessment', description: 'Created via Postman', instructions: 'Answer briefly.', startDate: '2026-11-01', dueDate: '2026-12-30', gradingConfig: { maxScore: 50 } }, expect: 201, response: 'Assessment (status ALWAYS draft)', errors: { ...common, 400: 'Validation failed' }, test: set('assessmentId', 'pm.response.json().data._id') }),
  E('Assessments', 'List assessments', 'GET', '/instructor/assessments', { query: { cohortId: '', status: '' }, response: 'Assessment[] with submissions counts' }),
  E('Assessments', 'Get assessment', 'GET', '/instructor/assessments/{{assessmentId}}', { response: 'Assessment + submissions{submitted,pendingGrading,evaluated,resultsPublished}' }),
  E('Assessments', 'Edit draft assessment', 'PATCH', '/instructor/assessments/{{assessmentId}}', { body: { title: 'Postman Assessment v2' }, response: 'Assessment', errors: { ...common, 409: 'Only draft assessments can be edited' } }),
  E('Assessments', 'Publish assessment', 'POST', '/instructor/assessments/{{assessmentId}}/publish', { response: 'Assessment (status published)', errors: { ...common, 409: 'Already published', 422: 'Missing description/instructions' } }),
  E('Assessments', 'Create throwaway draft', 'POST', '/instructor/assessments', { body: { cohortId: '{{cohortId}}', title: 'Throwaway draft', description: 'to be deleted' }, expect: 201, response: 'Assessment (draft)', test: set('draftId', 'pm.response.json().data._id') }),
  E('Assessments', 'Delete draft assessment', 'DELETE', '/instructor/assessments/{{draftId}}', { response: '{ deleted: true }', errors: { ...common, 409: 'Only drafts can be deleted' } }),
  // ---------- Integration (future Student Project) — placed mid-flow to feed the grading steps
  E('Integration (future)', 'Sync enrollment', 'POST', '/integration/enrollments', { auth: I, role: 'service', body: { externalStudentId: 'stu-dev-001', name: 'Dev Student 01', email: 'dev.student01@example.test', cohortId: '{{cohortId}}' }, expect: 201, response: '{ studentId, enrollmentId, cohortId }', errors: { 400: 'Validation', 401: 'Bad API key', 404: 'Cohort not found' } }),
  E('Integration (future)', 'Receive student submission', 'POST', '/integration/submissions', { auth: I, role: 'service', body: { assessmentId: '{{assessmentId}}', externalStudentId: 'stu-dev-001', content: 'Answer text submitted from the Student Project' }, expect: 201, response: '{ submissionId, status: submitted } — notifies the instructor', errors: { 401: 'Bad API key', 403: 'Student not actively enrolled in the cohort', 404: 'Assessment not found', 409: 'Assessment not published OR duplicate submission' } }),
  E('Integration (future)', 'Published assessments (student-facing)', 'GET', '/integration/assessments', { auth: I, role: 'service', query: { cohortId: '{{cohortId}}' }, response: 'Published assessments only — drafts are never returned' }),
  // ---------- Submissions & grading
  E('Submissions', 'List submissions of assessment', 'GET', '/instructor/assessments/{{assessmentId}}/submissions', { response: 'Submission[] with student + result{status,score,publishedAt}', test: set('submissionId', 'pm.response.json().data[0]._id') }),
  E('Submissions', 'List all my submissions', 'GET', '/instructor/submissions', { query: { status: 'submitted', assessmentId: '', cohortId: '' }, response: 'Submission[]' }),
  E('Submissions', 'Get submission', 'GET', '/instructor/submissions/{{submissionId}}', { response: 'Submission + student + assessment + result|null' }),
  E('Grading', 'Save evaluation (not published)', 'PUT', '/instructor/submissions/{{submissionId}}/grade', { body: { score: 42, feedback: 'Solid work', strengths: 'Clarity', improvements: 'Add references' }, response: 'AssessmentResult (status evaluated) — NOT visible to students', errors: { ...common, 400: 'Empty body / negative score', 409: 'Result already published (locked)', 422: 'Score exceeds the assessment\'s configured maxScore' } }),
  E('Integration (future)', 'Published results — before publishing (must be empty for this student/assessment)', 'GET', '/integration/results', { auth: I, role: 'service', query: { externalStudentId: 'stu-dev-001', assessmentId: '{{assessmentId}}' }, response: 'Published results only', test: "pm.test('unpublished result is hidden', () => pm.expect(pm.response.json().data.length).to.eql(0));" }),
  E('Grading', 'Publish result', 'POST', '/instructor/submissions/{{submissionId}}/publish-result', { response: 'AssessmentResult (status published)', errors: { ...common, 409: 'Not evaluated yet OR already published' } }),
  E('Integration (future)', 'Published results — after publishing', 'GET', '/integration/results', { auth: I, role: 'service', query: { externalStudentId: 'stu-dev-001', assessmentId: '{{assessmentId}}' }, response: '[{ submission, assessment, score, feedback, strengths, improvements, publishedAt }]', test: "pm.test('published result is visible', () => { const d = pm.response.json().data; pm.expect(d.length).to.eql(1); pm.expect(d[0].score).to.eql(42); });" }),
  E('Integration (future)', 'Student attendance', 'GET', '/integration/attendance', { auth: I, role: 'service', query: { externalStudentId: 'stu-dev-001', cohortId: '{{cohortId}}' }, response: '[{ session, status, markedAt }]' }),
  // ---------- Progress
  E('Progress', 'Student progress', 'GET', '/instructor/progress', { query: { cohortId: '{{cohortId}}' }, response: 'Per student: attendance{totalSessions,present,absent,pending,attendancePercentage}, assessments{published,submitted,pendingGrading,graded,resultsPublished,notSubmitted}, trainingStatus' }),
  // ---------- Notifications
  E('Notifications', 'List notifications', 'GET', '/instructor/notifications', { query: { unread: '', page: '1', limit: '20' }, response: 'Notification[] + meta{page,limit,total,unreadCount}', test: set('notificationId', 'pm.response.json().data[0]._id') }),
  E('Notifications', 'Mark notification read', 'PATCH', '/instructor/notifications/{{notificationId}}/read', { response: 'Notification' }),
  E('Notifications', 'Mark all read', 'POST', '/instructor/notifications/read-all', { response: '{ updated: true }' }),
  // ---------- Profile
  E('Profile', 'Get profile', 'GET', '/instructor/profile', { response: 'User (safe)' }),
  E('Profile', 'Update profile', 'PATCH', '/instructor/profile', { body: { name: 'Dev Instructor Layla Hassan', phone: '+20000000001', preferredLanguage: 'en', professional: { title: 'Systems Engineer (dev data)' } }, response: 'User. Only name, phone, preferredLanguage, professional.* are accepted; role/email/status are ignored.' }),
  E('Profile', 'Change password', 'PUT', '/instructor/profile/password', { body: { currentPassword: '{{instructorPassword}}', newPassword: '{{instructorPassword}}' }, expect: 200, response: '{ message } — all other sessions are signed out', errors: { ...common, 400: 'Wrong current password / weak new password' } }),
  E('Auth', 'Logout (this session)', 'POST', '/auth/logout', { role: 'any authenticated', body: { refreshToken: '{{refreshToken}}' }, response: '{ loggedOut: true }' }),
];
